function initTabs(){const t=document.querySelectorAll(".tab-btn"),e=document.querySelectorAll(".tab-content");t.forEach(n=>{n.addEventListener("click",()=>{t.forEach(t=>{t.classList.remove("active")}),e.forEach(t=>t.classList.remove("active")),n.classList.add("active"),document.getElementById(n.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const t=document.getElementById("koppam-quiz-form"),e=document.getElementById("quiz-result"),n={q1:"2",q2:"1"};t&&t.addEventListener("submit",o=>{o.preventDefault();let i=0;const l=new FormData(t);for(let[t,e]of l.entries())n[t]===e&&i++;const a=Object.keys(n).length;e.textContent=i===a?`🎉 Perfect! ${i}/${a}`:`You scored ${i}/${a}`,e.style.color=i===a?"green":"orange"})}function initGalleryModal(){const t=document.getElementById("gallery-modal"),e=document.getElementById("modal-title"),n=document.getElementById("modal-desc"),o=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(o=>{o.addEventListener("click",()=>{e.textContent=o.getAttribute("data-title"),n.textContent=o.getAttribute("data-desc"),t.classList.add("active")})}),o&&o.addEventListener("click",()=>t.classList.remove("active")),window.addEventListener("click",e=>{e.target===t&&t.classList.remove("active")})}function initScrollTop(){const t=document.getElementById("btn-scroll-top");t&&(window.addEventListener("scroll",()=>t.classList.toggle("visible",window.scrollY>300)),t.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("battle-koppam/index.html",[{id:"koppam-battle",title:"Battle of Koppam",description:"Chola vs Chalukya conflict.",link:"battle-koppam/index.html#overview"},{id:"koppam-strategy",title:"Battle Strategy",description:"Tactics and key events at Koppam.",link:"battle-koppam/index.html#strategy"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});